{
  "title": "TB Transmission World",
  "perWatchSecond": 0.5,
  "levels": [
    {
      "kind": "hook",
      "title": "Contact Rate Impact",
      "goal": "See how contact rate changes infectious numbers.",
      "control": {
        "parameter": "beta",
        "label": "Contact rate",
        "lowEnd": "0.01",
        "highEnd": "0.10"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if contact rate doubles to 0.1?",
        "parameter": "beta",
        "value": 0.1
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 3.6,
        "time": 3.6,
        "relation": "higher",
        "by": 60
      },
      "effect": "The what-if world has 60 more infectious people at 3.6 years.",
      "prediction": {
        "prompt": "Will the what-if world be higher or lower?",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Result",
        "quote": "contact rate ($beta$), recruitment rate ($varLambda$), the loss of protection for the vaccination rate ($theta$), and rate of progression from the exposed class to the infectious class ($gamma$) were the most important factors."
      },
      "carryForward": "Higher contact rates increase infection peaks."
    },
    {
      "kind": "background",
      "title": "Vaccine Protection Loss",
      "goal": "Observe how vaccine protection loss affects vaccinated counts.",
      "control": {
        "parameter": "theta",
        "label": "Loss of vaccine protection",
        "lowEnd": "0.1",
        "highEnd": "1.0"
      },
      "watch": "v",
      "whatIf": {
        "prompt": "What if protection loss halves to 0.25?",
        "parameter": "theta",
        "value": 0.25
      },
      "difference": {
        "compartment": "v",
        "summary": "at",
        "at": 7.2,
        "time": 7.2,
        "relation": "higher",
        "by": 3
      },
      "effect": "The what-if world has 3 more vaccinated people at 7.2 years.",
      "prediction": {
        "prompt": "Will the what-if world be higher or lower?",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Mechanism proposed",
        "quote": "The total population is divided into six distinct compartments: susceptible $S(t)$, vaccinated $V(t)$, exposed $E(t)$, infectious $I(t)$, treated, $T(t)$ and recovered $R(t)$."
      },
      "carryForward": "Lower protection loss keeps more people vaccinated."
    },
    {
      "kind": "result",
      "title": "Progression Rate Effect",
      "goal": "Check how progression rate changes exposed numbers.",
      "control": {
        "parameter": "gamma",
        "label": "Progression to infectious",
        "lowEnd": "0.1",
        "highEnd": "1.0"
      },
      "watch": "e",
      "whatIf": {
        "prompt": "What if progression rate halves to 0.24?",
        "parameter": "gamma",
        "value": 0.24
      },
      "difference": {
        "compartment": "e",
        "summary": "at",
        "at": 10.8,
        "time": 10.8,
        "relation": "higher",
        "by": 40
      },
      "effect": "The what-if world has 40 more exposed people at 10.8 years.",
      "prediction": {
        "prompt": "Will the what-if world be higher or lower?",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "What the model shows",
        "quote": "We obtained $mathscr{R}_0 = 2.67$ for the estimated model parameters, which are greater than one, indicating that the tuberculosis is continuously multiplying."
      },
      "carryForward": "Slower progression keeps more people exposed longer."
    }
  ],
  "limits": [
    "Time unit is year.",
    "Parameters ending in 0 are starting values.",
    "Run both worlds for the level time."
  ]
}
